use vstd::prelude::*;
use vstd::seq::Seq;

verus! {

    // A sequence of four chars is "hard" if any adjacent pair is equal.
    spec fn is_hard(s: Seq<char>) -> bool {
        // We know s.len() == 4 when this is called.
        s[0] == s[1] || s[1] == s[2] || s[2] == s[3]
    }

    // Given exactly four characters in s, return "Bad" if it is hard,
    // otherwise return "Good".  The result is guaranteed non‐empty.
    fn solve(s: Vec<char>) -> Vec<char>
        requires
            s.len() == 4,
        ensures
            // The postcondition on the spec‐view of the result.
            result@ ==
                if is_hard(s@) {
                    Seq::from_slice(&['B','a','d'])
                } else {
                    Seq::from_slice(&['G','o','o','d'])
                },
        ensures
            result.len() > 0,
    {
        // extract the four characters
        let c0 = s[0];
        let c1 = s[1];
        let c2 = s[2];
        let c3 = s[3];

        if c0 == c1 || c1 == c2 || c2 == c3 {
            // hard ⇒ "Bad"
            let mut res: Vec<char> = Vec::new();
            res.push('B');
            res.push('a');
            res.push('d');
            res
        } else {
            // not hard ⇒ "Good"
            let mut res: Vec<char> = Vec::new();
            res.push('G');
            res.push('o');
            res.push('o');
            res.push('d');
            res
        }
    }
}

fn main() {
    // example
    let v = vec!['a','b','b','c'];
    let out = solve(v);
    // out == vec!['B','a','d']
}